#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Sorting Hat at sortinghat.mediatom.cc: the steps only the owner can do.
# Run it on your own computer, from a checkout; server steps go over SSH, each
# shown and confirmed first. See deploy/sorting-hat/README.md.

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
HOST_NAME=sortinghat.mediatom.cc
IMAGE=ghcr.io/thomas-sievering/accio-sorting-hat:stable-v1
REMOTE_DIR=/home/tom/sorting-hat
STATE_DIR=/data/configs/sorting-hat
ZERO_TRUST=https://one.dash.cloudflare.com/

# remote "what it does" COMMAND shows COMMAND, and runs it on the server once confirmed.
remote() {
  local what="$1" command="$2"
  say "$what, on $SERVER:"
  printf '    %s%s%s\n' "$DIM" "$command" "$RESET"
  if confirm "Run it now over ssh?"; then
    ssh -t "$SERVER" "$command" || { warn "it failed; fix it and re-run the wizard"; exit 1; }
  else
    SKIPPED+=("on $SERVER: $command")
  fi
}

# public_check NAME PATH EXPECTED: one unauthenticated request to the public address.
public_check() {
  local name="$1" path="$2" expected="$3" result
  result="$(curl -s -o /dev/null -w '%{http_code} %{redirect_url}' "https://$HOST_NAME$path" || true)"
  if [[ "$result" == $expected ]]; then printf '  %s✓%s %s: %s\n' "$GREEN" "$RESET" "$name" "$result"
  else warn "$name: got '$result'"; SKIPPED+=("$name: expected $expected from https://$HOST_NAME$path, got '$result'"); fi
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE="${SORTING_HAT_WIZARD_ENV:-$HOME/.config/accio/sorting-hat-wizard.env}"
mkdir -p "$(dirname "$ENV_FILE")"

banner "Sorting Hat on the home server"

stage "Published image and server"
say "The server runs the image CI publishes from main, as the hub does."
open_url "https://github.com/thomas-sievering/accio/actions/workflows/sorting-hat.yml"
step "Check that the newest run on main succeeded, including its 'image' job."
step "If it never ran, merge the deploy change to main (or 'Run workflow' on main) first."
pause "Press Enter once a main run has published $IMAGE"
say "Server steps run over ssh, as the user that runs the hub's updater (tom)."
ask SERVER "SSH destination of the home server (for example tom@homeserver):"
write_env SERVER "$SERVER"

stage "Server: folders and files"
say "Its own Compose project in $REMOTE_DIR, and a state folder only UID 1000 can read."
remote "Look at what is there already" \
  "ls -la $REMOTE_DIR $STATE_DIR 2>&1; docker ps -a --filter name=sorting-hat"
remote "Create both folders (sudo, for /data/configs)" \
  "mkdir -p $REMOTE_DIR ~/.config/systemd/user && sudo install -d -o 1000 -g 1000 -m 700 $STATE_DIR"
say "Copy compose.yaml, deploy.sh and the update timer from this checkout:"
if confirm "Copy them with scp now?"; then
  scp "$HERE/compose.yaml" "$HERE/deploy.sh" "$SERVER:$REMOTE_DIR/"
  scp "$HERE/sorting-hat-update.service" "$HERE/sorting-hat-update.timer" "$SERVER:.config/systemd/user/"
  ssh "$SERVER" "chmod 755 $REMOTE_DIR/deploy.sh"
else
  SKIPPED+=("copy compose.yaml and deploy.sh to $SERVER:$REMOTE_DIR, the two units to ~/.config/systemd/user")
fi
remote "Check the server can pull the image (the hub's ghcr.io login, a token with read:packages)" \
  "docker pull $IMAGE >/dev/null && echo pulled"

stage "Cloudflare Access: the dashboard"
say "One Access application for the whole host, allowing only you."
note "Cloudflare moves these screens around; the names below are from its docs."
open_url "$ZERO_TRUST"
step "Access controls → Applications → Create new application → Self-hosted and private."
step "Name: Sorting Hat. Add public hostname: subdomain sortinghat, domain mediatom.cc, path empty."
step "Access policies → create a policy: Action Allow, Include → Emails → your email."
step "Pick your identity provider (or One-time PIN), choose a session duration, Create."
step "Open the new application and copy its Application Audience (AUD) Tag."
ask SORTING_HAT_ACCESS_AUD "Paste the AUD tag:"
[[ "$SORTING_HAT_ACCESS_AUD" =~ ^[0-9a-f]{64}$ ]] || warn "an AUD tag is usually 64 hex characters; check you copied all of it"
write_env SORTING_HAT_ACCESS_AUD "$SORTING_HAT_ACCESS_AUD"
step "Settings (Zero Trust settings) shows your team domain, <team>.cloudflareaccess.com."
ask SORTING_HAT_ACCESS_TEAM_DOMAIN "Team domain (<team>.cloudflareaccess.com):"
SORTING_HAT_ACCESS_TEAM_DOMAIN="${SORTING_HAT_ACCESS_TEAM_DOMAIN#https://}"
SORTING_HAT_ACCESS_TEAM_DOMAIN="${SORTING_HAT_ACCESS_TEAM_DOMAIN%%/*}"
write_env SORTING_HAT_ACCESS_TEAM_DOMAIN "$SORTING_HAT_ACCESS_TEAM_DOMAIN"

stage "Cloudflare Access: bypass the model routes"
say "Claude Code, pi and Codex cannot sign in to Access; their routes take hat keys instead."
say "A more specific application wins over the dashboard's, so a second one bypasses them."
open_url "$ZERO_TRUST"
step "Access controls → Applications → Create new application → Self-hosted and private."
step "Name: Sorting Hat model routes. Add two public hostnames, both sortinghat · mediatom.cc:"
step "  path  v1/*      (Claude Code: /v1/messages, /v1/messages/count_tokens, /v1/models)"
step "  path  openai/*  (Codex: /openai/responses, /openai/responses/compact)"
step "Access policies → create a policy: Action Bypass, Include → Everyone. Create."
warn "Leave /api/* and / alone: the dashboard and management API stay behind Access."
pause "Press Enter once both applications exist"

stage "Server: settings, first start and updates"
say "Write .secrets.env (mode 600) with the Access settings, beside compose.yaml."
if confirm "Write $REMOTE_DIR/.secrets.env on $SERVER now?"; then
  printf 'SORTING_HAT_ACCESS_TEAM_DOMAIN=%s\nSORTING_HAT_ACCESS_AUD=%s\n' \
    "$SORTING_HAT_ACCESS_TEAM_DOMAIN" "$SORTING_HAT_ACCESS_AUD" \
    | ssh "$SERVER" "umask 077 && cat > $REMOTE_DIR/.secrets.env"
  printf '  %s✓ wrote%s .secrets.env on %s\n' "$GREEN" "$RESET" "$SERVER"
else
  SKIPPED+=("write $REMOTE_DIR/.secrets.env on $SERVER with the team domain and AUD tag")
fi
remote "Deploy the stable image once; it waits for health" \
  "cd $REMOTE_DIR && ./deploy.sh && docker logs sorting-hat 2>&1 | grep -v 'hat-admin-'"
remote "Turn on automatic updates (check Linger=yes)" \
  "systemctl --user daemon-reload && systemctl --user enable --now sorting-hat-update.timer && loginctl show-user \$USER -p Linger"

stage "Cloudflare Tunnel: the public hostname"
say "Route $HOST_NAME on the existing homeserver tunnel to the container."
open_url "$ZERO_TRUST"
step "Networks → Tunnels (Connectors) → the homeserver tunnel → Configure / Edit."
step "Published application routes → Add: subdomain sortinghat, domain mediatom.cc, path empty."
step "Service: type HTTP, URL sorting-hat:47330. Save."
warn "Do not turn on 'Protect with Access' in the route's origin settings: it would block the model routes."
pause "Press Enter once the route is saved"

stage "Admin token"
say "The Sorting Hat created its admin token on first start, in $STATE_DIR/admin-token."
say "The hub uses it from the server, at http://sorting-hat:47330, never through Cloudflare."
remote "Show the admin token" "docker exec sorting-hat cat /data/admin-token"
step "Put it in your password manager. Give it to the hub when linking it to the Sorting Hat,"
step "with the address http://sorting-hat:47330. Never paste it into a client or a chat."
pause "Press Enter once it is saved"

stage "Check it from outside"
say "Two requests without credentials. The dashboard's API must redirect to Access;"
say "a model route must reach the Sorting Hat and get its own 401."
public_check "management API behind Access" /api/houses "30[0-9] https://*cloudflareaccess.com*"
public_check "model route bypasses Access" /v1/models "401 "
open_url "https://$HOST_NAME/"
step "The browser should ask you to sign in with Access, then show the Sorting Hat."
note "Then make a hat key and try Claude Code:"
note "  ANTHROPIC_BASE_URL=https://$HOST_NAME ANTHROPIC_AUTH_TOKEN=<hat key> claude"
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
